function prep(g) {
  const geo = g.index ? g.toNonIndexed() : g
  for (const k of Object.keys(geo.attributes)) {
    if (!['position', 'normal', 'uv'].includes(k)) geo.deleteAttribute(k)
  }
  if (!geo.attributes.uv) {
    const n = geo.attributes.position.count
    geo.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(n * 2), 2))
  }
  return geo
}

function transform(g, x, y, z, rx = 0, ry = 0, rz = 0) {
  const m = new THREE.Matrix4()
  const e = new THREE.Euler(rx, ry, rz, 'XYZ')
  m.compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromEuler(e), new THREE.Vector3(1, 1, 1))
  g.applyMatrix4(m)
  return g
}

function beamGeo(a, b, thick) {
  const dir = new THREE.Vector3().subVectors(b, a)
  const len = dir.length()
  const g = new THREE.BoxGeometry(len, thick, thick)
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(1, 0, 0), dir.clone().normalize())
  const m = new THREE.Matrix4().compose(a.clone().addScaledVector(dir, 0.5), q, new THREE.Vector3(1, 1, 1))
  g.applyMatrix4(m)
  return g
}

function cabinGlassGeometry(spec, cab) {
  const L = spec.length, W = spec.width, H = spec.height
  const yB = H * (BODY_GEOM[spec.body].belt) - 0.015
  const yT = H * cab.roofY
  const xB = W * 0.442, xT = W * 0.352
  const rearB = L * cab.baseRear, frontB = L * cab.baseFront
  const rearT = L * cab.roofRear, frontT = L * cab.roofFront
  const quads = [
    // left side
    [[-xB, yB, rearB], [-xB, yB, frontB], [-xT, yT, frontT], [-xT, yT, rearT]],
    // right side
    [[xB, yB, frontB], [xB, yB, rearB], [xT, yT, rearT], [xT, yT, frontT]],
    // windshield
    [[-xB, yB, frontB], [xB, yB, frontB], [xT, yT, frontT], [-xT, yT, frontT]],
    // rear glass
    [[xB, yB, rearB], [-xB, yB, rearB], [-xT, yT, rearT], [xT, yT, rearT]]
  ]
  const pos = []
  for (const q of quads) {
    pos.push(...q[0], ...q[1], ...q[2], ...q[0], ...q[2], ...q[3])
  }
  const g = new THREE.BufferGeometry()
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3))
  const uv = []
  for (let i = 0; i < pos.length / 3; i++) uv.push((i % 2), (i % 3) / 2)
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2))
  g.computeVertexNormals()
  return g
}

function createWheel(spec, mats, style, simple) {
  const r = spec.wheelR
  const width = simple ? 0.22 : 0.235
  const pivot = new THREE.Group()
  const spin = new THREE.Group()
  pivot.add(spin)
  const tire = new THREE.Mesh(new THREE.CylinderGeometry(r, r, width, simple ? 14 : 22), mats.rubber)
  tire.rotation.z = Math.PI / 2
  tire.castShadow = false
  spin.add(tire)
  const rimRadius = r * (0.63 + (style % 3) * 0.02)
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(rimRadius, rimRadius, width + 0.008, 22), mats.rim)
  rim.rotation.z = Math.PI / 2
  spin.add(rim)
  const spokes = []
  const count = [5, 10, 8, 5, 7][style % 5]
  for (let i = 0; i < count; i++) {
    const a = i / count * TAU
    const geo = new THREE.BoxGeometry(width + 0.02, 0.036, rimRadius * 0.88)
    transform(geo, 0, Math.cos(a) * rimRadius * 0.46, Math.sin(a) * rimRadius * 0.46, a, 0, 0)
    spokes.push(geo)
  }
  const mergedSpokes = mergeGeometries(spokes.map(prep))
  if (mergedSpokes) {
    const sm = new THREE.Mesh(mergedSpokes, style % 2 ? mats.rim : mats.rimDark)
    spin.add(sm)
  }
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(rimRadius * 0.25, rimRadius * 0.25, width + 0.035, 12), mats.chrome)
  hub.rotation.z = Math.PI / 2
  spin.add(hub)
  const disc = new THREE.Mesh(new THREE.CylinderGeometry(rimRadius * 0.72, rimRadius * 0.72, 0.03, 18), mats.disc)
  disc.rotation.z = Math.PI / 2
  disc.position.x = 0.02
  pivot.add(disc)
  const cal = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.11, 0.16), mats.caliper)
  cal.position.set(0.03, 0.03, -rimRadius * 0.66)
  pivot.add(cal)
  return { pivot, spin, radius: r, width }
}

export function buildCar(spec, options = {}) {
  const {
    paint = spec.defaultColor, wheelStyle = spec.wheelStyle, rideHeight = 0, spoiler = null,
    tint = 0, simple = false, lights3d = false, plate = null, quality = 'high'
  } = options
  const mats = MAT()
  const bodyMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(paint), metalness: 0.55, roughness: 0.26,
    clearcoat: 1.0, clearcoatRoughness: 0.055, envMapIntensity: 1.15
  })
  mats.paint = bodyMat
  if (tint > 0) mats.glass.opacity = clamp(0.78 + tint * 0.18, 0.7, 0.97)
  const group = new THREE.Group()
  const bodyGroup = new THREE.Group()
  group.add(bodyGroup)

  const L = spec.length, W = spec.width, H = spec.height
  const wheelbase = spec.wheelbase
  const profile = BODY_GEOM[spec.body] || BODY_GEOM.hatch
  const cab = CABIN[spec.body] || CABIN.hatch
  const groundClear = 0.13 + (spec.body === 'suv' ? 0.09 : 0)
  const beltY = H * profile.belt
  const frontAxle = wheelbase * 0.5
  const rearAxle = -wheelbase * 0.5
  const axleX = spec.track * 0.5 - 0.035

  const parts = {}
  const add = (key, geo) => {
    if (!parts[key]) parts[key] = []
    parts[key].push(prep(geo))
  }
  const addBox = (key, w, h, d, x, y, z, rx = 0, ry = 0, rz = 0) => {
    add(key, transform(new THREE.BoxGeometry(w, h, d), x, y, z, rx, ry, rz))
  }

  // ---- main body: side profile extruded across the width ----
  const shape = new THREE.Shape()
  const pts = profile.points
  // reduce absolute Y values by factoring the height in
  const fixedPts = pts.map(([zf, yf]) => [zf * L, yf > 1 ? yf : (yf < 0.7 ? yf : yf) * (yf > 0.7 ? H : 1)])
  // profile points store Y factors below 1 as fractions of H, others absolute
  const scaled = pts.map(([zf, yf]) => [zf * L, yf * H * (yf < 0.7 ? 1 : 0.92)])
  shape.moveTo(scaled[0][0], scaled[0][1])
  for (let i = 1; i < scaled.length; i++) shape.lineTo(scaled[i][0], scaled[i][1])
  shape.closePath()
  const depth = W - 0.09
  const extrude = new THREE.ExtrudeGeometry(shape, {
    depth, bevelEnabled: true, bevelThickness: 0.035, bevelSize: 0.035, bevelSegments: 2, steps: 1
  })
  extrude.rotateY(-Math.PI / 2)
  extrude.translate(depth / 2 + 0.02, 0, 0)
  add('paint', extrude)

  // rocker / lower body shadow strip
  addBox('under', W * 0.94, 0.14, L * 0.66, 0, 0.17, 0)

  // ---- cabin greenhouse ----
  add('glass', cabinGlassGeometry(spec, cab))
  const yRoof = H * cab.roofY
  const roofW = W * 0.70
  const roofRear = L * cab.roofRear, roofFront = L * cab.roofFront
  const roof = new RoundedBoxGeometry(roofW, 0.055, Math.abs(roofFront - roofRear) + 0.06, 2, 0.02)
  transform(roof, 0, yRoof + 0.012, (roofFront + roofRear) / 2)
  add('paint', roof)
  // pillars
  const yB = beltY - 0.02
  const xB = W * 0.435, xT = W * 0.345
  const bRear = L * cab.baseRear, bFront = L * cab.baseFront
  const tRear = L * cab.roofRear, tFront = L * cab.roofFront
  for (const sx of [-1, 1]) {
    add('paint', beamGeo(new THREE.Vector3(sx * xB, yB, bFront), new THREE.Vector3(sx * xT, yRoof, tFront), 0.075))
    add('paint', beamGeo(new THREE.Vector3(sx * xB, yB, bRear), new THREE.Vector3(sx * xT, yRoof, tRear), 0.07))
    add('black', beamGeo(new THREE.Vector3(sx * (xB + 0.002), yB - 0.005, (bRear + bFront) * 0.42), new THREE.Vector3(sx * (xT + 0.002), yRoof - 0.03, (tRear + tFront) * 0.44), 0.035))
    // window trim
    add('chrome', beamGeo(new THREE.Vector3(sx * (xB + 0.003), yB, bRear + 0.04), new THREE.Vector3(sx * (xB + 0.003), yB, bFront - 0.04), 0.018))
  }
  add('chrome', beamGeo(new THREE.Vector3(-xB, yB, bRear), new THREE.Vector3(-xB, yB, bFront), 0.018))
  add('chrome', beamGeo(new THREE.Vector3(xB, yB, bRear), new THREE.Vector3(xB, yB, bFront), 0.018))

  // roof rails for tall cars
  if (['wagon', 'suv', 'mpv'].includes(spec.body)) {
    for (const sx of [-1, 1]) {
      addBox('black', 0.045, 0.035, Math.abs(roofFront - roofRear) * 0.88, sx * roofW * 0.37, yRoof + 0.07, (roofFront + roofRear) / 2)
      addBox('black', 0.045, 0.06, 0.06, sx * roofW * 0.37, yRoof + 0.04, roofRear + 0.2)
      addBox('black', 0.045, 0.06, 0.06, sx * roofW * 0.37, yRoof + 0.04, roofFront - 0.2)
    }
  }

  // ---- front fascia ----
  const frontZ = L * 0.5 - 0.02
  const headY = H * 0.505
  const headX = W * 0.315
  for (const sx of [-1, 1]) {
    if (spec.lights === 'round') {
      add('black', transform(new THREE.CylinderGeometry(0.115, 0.125, 0.06, 18), sx * headX, headY, frontZ + 0.015, Math.PI / 2, 0, 0))
      add('headlight', transform(new THREE.CylinderGeometry(0.09, 0.095, 0.055, 18), sx * headX, headY, frontZ + 0.03, Math.PI / 2, 0, 0))
      add('headlight', transform(new THREE.CylinderGeometry(0.105, 0.115, 0.018, 18), sx * headX, headY + 0.005, frontZ + 0.06, Math.PI / 2, 0, 0.35 * sx))
    } else if (spec.lights === 'led') {
      addBox('headlight', W * 0.25, 0.085, 0.05, sx * headX, headY, frontZ + 0.02, 0, 0, sx * 0.09)
      addBox('black', W * 0.28, 0.13, 0.05, sx * headX, headY, frontZ)
      addBox('headlight', W * 0.20, 0.028, 0.02, sx * headX, headY - 0.045, frontZ + 0.05)
    } else {
      addBox('black', W * 0.28, 0.19, 0.06, sx * headX, headY, frontZ))
      addBox('headlight', W * 0.235, 0.13, 0.05, sx * headX, headY, frontZ + 0.025)
      addBox('headlight', W * 0.10, 0.04, 0.02, sx * (headX - 0.06), headY + 0.055, frontZ + 0.06)
    }
    // indicators at bumper corners
    addBox('indicator', 0.10, 0.045, 0.03, sx * (W * 0.41), H * 0.33, frontZ + 0.02)
  }
  // grille with brand details
  const grilleY = H * 0.40
  const grille = new RoundedBoxGeometry(W * 0.36, H * 0.105, 0.05, 2, 0.012)
  transform(grille, 0, grilleY, frontZ + 0.015)
  add('blackMatte', grille)
  if (spec.grille === 'bmw') {
    for (const sx of [-1, 1]) {
      addBox('chrome', W * 0.135, H * 0.13, 0.06, sx * W * 0.085, grilleY, frontZ + 0.025)
      addBox('blackMatte', W * 0.105, H * 0.105, 0.065, sx * W * 0.085, grilleY, frontZ + 0.03)
    }
  } else {
    for (let i = 0; i < 4; i++) {
      addBox('chrome', W * 0.335, 0.014, 0.02, 0, grilleY - H * 0.038 + i * H * 0.028, frontZ + 0.05)
    }
  }
  // headlight trim / bumper
  const frontBumper = new RoundedBoxGeometry(W * 0.955, H * 0.19, 0.26, 3, 0.06)
  transform(frontBumper, 0, H * 0.235, L * 0.5 - 0.12)
  const frontBumperMesh = new THREE.Mesh(frontBumper, mats.paint)
  frontBumperMesh.castShadow = true; frontBumperMesh.receiveShadow = true
  bodyGroup.add(frontBumperMesh)
  addBox('blackMatte', W * 0.58, H * 0.10, 0.08, 0, H * 0.17, frontZ + 0.06)
  addBox('blackMatte', W * 0.88, 0.07, 0.13, 0, H * 0.105, L * 0.5 - 0.09)
  // splitter
  addBox('blackMatte', W * 0.80, 0.025, 0.2, 0, 0.10, L * 0.5 - 0.1)
  // fog lights
  for (const sx of [-1, 1]) addBox('headlight', 0.09, 0.05, 0.03, sx * W * 0.33, H * 0.20, frontZ + 0.08)

  // ---- rear ----
  const rearZ = -L * 0.5 + 0.02
  for (const sx of [-1, 1]) {
    addBox('taillight', W * 0.25, H * 0.115, 0.055, sx * W * 0.31, H * 0.50, rearZ - 0.015, 0, 0, sx * -0.06)
    addBox('reverse', W * 0.075, 0.035, 0.02, sx * W * 0.29, H * 0.455, rearZ - 0.05)
    addBox('indicator', 0.055, 0.045, 0.02, sx * W * 0.405, H * 0.53, rearZ - 0.04)
    addBox('blackMatte', 0.11, 0.075, 0.14, sx * W * 0.26, 0.105, rearZ - 0.08)
    addBox('chrome', 0.075, 0.075, 0.16, sx * W * 0.26, 0.10, rearZ - 0.09)
  }
  const rearBumper = new RoundedBoxGeometry(W * 0.955, H * 0.20, 0.24, 3, 0.06)
  transform(rearBumper, 0, H * 0.24, -L * 0.5 + 0.11)
  const rearBumperMesh = new THREE.Mesh(rearBumper, mats.paint)
  rearBumperMesh.castShadow = true; rearBumperMesh.receiveShadow = true
  bodyGroup.add(rearBumperMesh)
  addBox('blackMatte', W * 0.60, 0.09, 0.05, 0, H * 0.17, rearZ - 0.07)
  // reflectors
  for (const sx of [-1, 1]) addBox('taillight', 0.11, 0.03, 0.02, sx * W * 0.38, H * 0.22, rearZ - 0.025)
  // wiper
  addBox('blackMatte', 0.42, 0.012, 0.02, -0.05, beltY + 0.01, L * 0.17, 0.22, 0, 0.12)

  // ---- mirrors, handles, side details ----
  for (const sx of [-1, 1]) {
    addBox('paint', 0.13, 0.085, 0.17, sx * (W * 0.5 + 0.035), beltY + 0.035, L * 0.075, 0, 0, 0)
    addBox('black', 0.05, 0.04, 0.07, sx * (W * 0.475), beltY - 0.01, L * 0.075)
    addBox('chrome', 0.025, 0.028, 0.11, sx * (W * 0.474), beltY - 0.02, L * 0.13)
    addBox('chrome', 0.025, 0.028, 0.11, sx * (W * 0.474), beltY - 0.02, -L * 0.10)
    // door seams
    addBox('blackMatte', 0.012, beltY * 0.72, 0.018, sx * (W * 0.478), H * 0.36, L * 0.0)
    addBox('blackMatte', 0.012, 0.15, 0.018, sx * (W * 0.478), H * 0.47, -L * 0.235)
    // side skirts
    addBox('blackMatte', 0.07, 0.10, L * 0.52, sx * (W * 0.48), 0.16, 0)
    // wheel arch trim
    for (const az of [frontAxle, rearAxle]) {
      const torus = new THREE.TorusGeometry(spec.wheelR + 0.075, 0.035, 5, 14, Math.PI)
      torus.rotateY(Math.PI / 2); torus.rotateX(0)
      transform(torus, sx * (W * 0.475), spec.wheelR + 0.01, az)
      add('blackMatte', torus)
    }
  }
  // exhaust
  for (const sx of spec.body === 'suv' ? [-1, 1] : [1]) {
    const ex = new THREE.CylinderGeometry(0.038, 0.044, 0.16, 10)
    ex.rotateX(Math.PI / 2)
    transform(ex, sx * W * 0.24, 0.10, rearZ - 0.05)
    add('chrome', ex)
    const inner = new THREE.CylinderGeometry(0.028, 0.028, 0.04, 8)
    inner.rotateX(Math.PI / 2)
    transform(inner, sx * W * 0.24, 0.10, rearZ - 0.13)
    add('blackMatte', inner)
  }
  // antenna
  addBox('blackMatte', 0.018, 0.16, 0.018, 0, yRoof + 0.09, L * cab.roofRear + 0.2, 0.15, 0, 0)

  // ---- spoiler ----
  const hasSpoiler = spoiler != null ? spoiler : spec.spoiler > 0.38
  if (hasSpoiler) {
    const size = spoiler != null ? spoiler : spec.spoiler
    const wingY = yRoof - H * 0.02
    const wingZ = rearZ - 0.05
    addBox('blackMatte', 0.06, 0.16, 0.12, -W * 0.28, wingY - 0.02, wingZ)
    addBox('blackMatte', 0.06, 0.16, 0.12, W * 0.28, wingY - 0.02, wingZ)
    addBox(spec.body === 'suv' ? 'blackMatte' : 'paint', W * 0.72, 0.035, 0.28, 0, wingY + 0.08, wingZ)
  }

  // ---- license plates & badges ----
  const plateMat = new THREE.MeshStandardMaterial({ map: plateTexture(plate || `BI ${1000 + (spec.id.length * 137) % 8999} ${String.fromCharCode(65 + spec.id.length % 26)}${String.fromCharCode(65 + (spec.id.length * 3) % 26)}`), roughness: 0.45 })
  const frontPlate = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.115), plateMat)
  frontPlate.position.set(0, H * 0.22, L * 0.5 + 0.005)
  bodyGroup.add(frontPlate)
  const rearPlate = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.115), plateMat)
  rearPlate.position.set(0, H * 0.245, -L * 0.5 - 0.005)
  rearPlate.rotation.y = Math.PI
  bodyGroup.add(rearPlate)
  const badgeMat = new THREE.MeshBasicMaterial({ map: brandTexture(spec.brand), transparent: true })
  const frontBadge = new THREE.Mesh(new THREE.PlaneGeometry(0.125, 0.125), badgeMat)
  frontBadge.position.set(0, H * 0.43, L * 0.5 + 0.045)
  bodyGroup.add(frontBadge)
  const rearBadge = new THREE.Mesh(new THREE.PlaneGeometry(0.11, 0.11), badgeMat)
  rearBadge.position.set(0, H * 0.42, -L * 0.5 - 0.008)
  rearBadge.rotation.y = Math.PI
  bodyGroup.add(rearBadge)
  const nameMat = new THREE.MeshBasicMaterial({ map: nameTexture(spec.model), transparent: true, opacity: 0.85 })
  const rearName = new THREE.Mesh(new THREE.PlaneGeometry(0.42, 0.10), nameMat)
  rearName.position.set(W * 0.29, H * 0.40, -L * 0.5 - 0.006)
  rearName.rotation.y = Math.PI
  bodyGroup.add(rearName)

  // ---- interior ----
  if (!simple) {
    addBox('interior', W * 0.82, 0.16, L * 0.54, 0, beltY - 0.06, -L * 0.02)
    // seats
    for (const sx of [-1, 1]) {
      const base = new RoundedBoxGeometry(0.46, 0.13, 0.52, 2, 0.04)
      transform(base, sx * W * 0.20, beltY + 0.03, -L * 0.10)
      add('interiorLight', base)
      const back = new RoundedBoxGeometry(0.46, 0.52, 0.14, 2, 0.05)
      transform(back, sx * W * 0.20, beltY + 0.28, -L * 0.205, -0.18)
      add('interiorLight', back)
      const head = new RoundedBoxGeometry(0.26, 0.15, 0.13, 2, 0.04)
      transform(head, sx * W * 0.20, beltY + 0.58, -L * 0.23, -0.18)
      add('interior', head)
    }
    // dashboard
    const dash = new RoundedBoxGeometry(W * 0.82, 0.16, 0.30, 3, 0.04)
    transform(dash, 0, beltY + 0.04, L * 0.14)
    add('interior', dash)
    addBox('chrome', W * 0.40, 0.012, 0.02, -W * 0.13, beltY + 0.125, L * 0.19)
    // centre console / screen
    addBox('interior', W * 0.20, 0.25, 0.32, W * 0.16, beltY - 0.01, L * 0.12)
    addBox('screen', W * 0.14, 0.075, 0.012, W * 0.16, beltY + 0.15, L * 0.092)
    // rear view mirror
    addBox('black', 0.23, 0.045, 0.035, 0, yRoof - 0.06, L * 0.17)
    addBox('mirror', 0.20, 0.07, 0.015, 0, yRoof - 0.065, L * 0.155)
  }

  // ---- merge static parts ----
  const partMeshes = {}
  for (const [key, geos] of Object.entries(parts)) {
    const merged = mergeGeometries(geos, false)
    if (!merged) continue
    const mat = mats[key] || mats.black
    const mesh = new THREE.Mesh(merged, mat)
    mesh.castShadow = quality !== 'low'
    mesh.receiveShadow = quality !== 'low'
    bodyGroup.add(mesh)
    partMeshes[key] = mesh
  }

  // ---- wheels ----
  const wheels = []
  const wheelPivots = []
  for (const [sx, az, isFront] of [[-1, frontAxle, true], [1, frontAxle, true], [-1, rearAxle, false], [1, rearAxle, false]]) {
    const w = createWheel(spec, mats, wheelStyle, simple)
    w.pivot.position.set(sx * axleX, spec.wheelR, az)
    group.add(w.pivot)
    wheels.push({ ...w, isFront, side: sx })
    wheelPivots.push(w.pivot)
  }

  // ---- lights ----
  const headGlowMat = () => new THREE.SpriteMaterial({
    map: radialTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)'),
    color: 0xffe6bb, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0
  })
  const headGlows = []
  for (const sx of [-1, 1]) {
    const s = new THREE.Sprite(headGlowMat())
    s.position.set(sx * headX, headY, L * 0.5 + 0.1)
    s.scale.setScalar(1.4)
    bodyGroup.add(s)
    headGlows.push(s)
  }
  const tailGlows = []
  for (const sx of [-1, 1]) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({
      map: radialTexture('rgba(255,80,70,1)', 'rgba(255,0,0,0)'),
      color: 0xff2222, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0
    }))
    s.position.set(sx * W * 0.31, H * 0.50, -L * 0.5 - 0.1)
    s.scale.setScalar(0.9)
    bodyGroup.add(s)
    tailGlows.push(s)
  }

  let spotL = null, spotR = null
  if (lights3d) {
    const target = new THREE.Object3D()
    target.position.set(0, 0, 32)
    bodyGroup.add(target)
    const mk = (x) => {
      const sp = new THREE.SpotLight(0xffe9c8, 0, 80, 0.48, 0.55, 1.35)
      sp.position.set(x, headY, L * 0.5 + 0.06)
      sp.target = target
      sp.visible = false
      sp.castShadow = false
      bodyGroup.add(sp)
      return sp
    }
    spotL = mk(-headX); spotR = mk(headX)
  }

  // ---- blob shadow ----
  const shadowTex = radialTexture('rgba(0,0,0,0.65)', 'rgba(0,0,0,0)', 0.5)
  const shadowMat = new THREE.MeshBasicMaterial({ map: shadowTex, transparent: true, opacity: 0.62, depthWrite: false, color: 0x000000 })
  const shadow = new THREE.Mesh(new THREE.PlaneGeometry(W * 1.45, L * 1.12), shadowMat)
  shadow.rotation.x = -Math.PI / 2
  shadow.position.y = 0.022
  group.add(shadow)
  group.userData.shadow = shadow

  // ---- cockpit / dashboard ----
  let cockpit = null
  if (!simple) {
    const dashCanvas = document.createElement('canvas')
    dashCanvas.width = 512; dashCanvas.height = 256
    const dashTex = new THREE.CanvasTexture(dashCanvas)
    dashTex.colorSpace = THREE.SRGBColorSpace
    const cluster = new THREE.Mesh(new THREE.PlaneGeometry(0.46, 0.23), new THREE.MeshBasicMaterial({ map: dashTex, transparent: true }))
    const clusterX = -W * 0.20
    cluster.position.set(clusterX, beltY + 0.095, L * 0.205)
    cluster.rotation.x = -0.18
    cluster.rotation.y = Math.PI
    bodyGroup.add(cluster)
    const wheelGroup = new THREE.Group()
    const wheelPos = new THREE.Vector3(clusterX, beltY - 0.03, L * 0.10)
    wheelGroup.position.copy(wheelPos)
    wheelGroup.rotation.x = -0.32
    const spinGroup = new THREE.Group()
    wheelGroup.add(spinGroup)
    const rim = new THREE.Mesh(new THREE.TorusGeometry(0.17, 0.018, 8, 26), new THREE.MeshStandardMaterial({ color: 0x161719, roughness: 0.6 }))
    spinGroup.add(rim)
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.03, 16), new THREE.MeshStandardMaterial({ color: 0x222326, roughness: 0.45, metalness: 0.4 }))
    hub.rotation.x = Math.PI / 2
    spinGroup.add(hub)
    const spokeMat = new THREE.MeshStandardMaterial({ color: 0x24262a, roughness: 0.5, metalness: 0.35 })
    for (let i = 0; i < 3; i++) {
      const sp = new THREE.Mesh(new THREE.BoxGeometry(0.026, 0.30, 0.02), spokeMat)
      sp.rotation.z = i * Math.PI * 2 / 3 + Math.PI / 2
      sp.position.z = 0.002
      spinGroup.add(sp)
    }
    bodyGroup.add(wheelGroup)
    cockpit = {
      position: new THREE.Vector3(-W * 0.19, beltY + 0.33, -L * 0.015),
      lookAt: new THREE.Vector3(-W * 0.16, beltY + 0.28, L * 0.35),
      dashCanvas, dashTex, spinGroup, wheelGroup
    }
  }

  // adjust ride height
  bodyGroup.position.y = rideHeight
  for (const w of wheelPivots) w.position.y = spec.wheelR + rideHeight * 0.35

  const state = {
    headlights: false, brake: false, reverse: false, indicator: 0, blink: false
  }

  function updateLights(next = {}) {
    Object.assign(state, next)
    const on = state.headlights
    mats.headlight.emissiveIntensity = on ? 2.4 : 0.06
    mats.indicator.emissiveIntensity = state.indicator !== 0 && state.blink ? 2.2 : 0.0
    mats.reverse.emissiveIntensity = state.reverse ? 1.9 : 0.0
    mats.taillight.emissiveIntensity = state.brake ? 2.6 : (on ? 0.9 : 0.35)
    for (const g of headGlows) g.material.opacity = on ? 0.55 : 0
    for (const g of tailGlows) g.material.opacity = state.brake ? 0.6 : (on ? 0.22 : 0)
    if (spotL) { spotL.visible = on; spotR.visible = on; spotL.intensity = on ? 90 : 0; spotR.intensity = on ? 90 : 0 }
  }

  function updateDashboard(speed, rpm, gear, throttle) {
    if (!cockpit) return
    const ctx = cockpit.dashCanvas.getContext('2d')
    const Wc = 512, Hc = 256
    ctx.clearRect(0, 0, Wc, Hc)
    // panel
    const g = ctx.createLinearGradient(0, 0, 0, Hc)
    g.addColorStop(0, 'rgba(16,18,22,0.92)'); g.addColorStop(1, 'rgba(5,6,8,0.96)')
    ctx.fillStyle = g; ctx.fillRect(0, 0, Wc, Hc)
    ctx.strokeStyle = 'rgba(160,170,180,0.25)'; ctx.lineWidth = 3
    ctx.strokeRect(3, 3, Wc - 6, Hc - 6)

    const drawGauge = (cx, cy, r, value, max, label, redline = null, step = 1) => {
      ctx.save()
      ctx.translate(cx, cy)
      ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU)
      ctx.fillStyle = 'rgba(8,9,11,0.95)'; ctx.fill()
      ctx.strokeStyle = 'rgba(180,190,200,0.45)'; ctx.lineWidth = 2; ctx.stroke()
      const a0 = Math.PI * 0.78, a1 = Math.PI * 2.22
      for (let i = 0; i <= 40; i++) {
        const t = i / 40
        const a = a0 + (a1 - a0) * t
        const major = i % 5 === 0
        const isRed = redline != null && t > redline
        ctx.strokeStyle = isRed ? '#ff3030' : (major ? '#dfe4e8' : 'rgba(200,210,220,0.55)')
        ctx.lineWidth = major ? 3 : 1.5
        const r0 = r * 0.80, r1 = r * (major ? 0.92 : 0.87)
        ctx.beginPath()
        ctx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0)
        ctx.lineTo(Math.cos(a) * r1, Math.sin(a) * r1)
        ctx.stroke()
        if (major) {
          ctx.fillStyle = isRed ? '#ff5a5a' : '#c9d1d8'
          ctx.font = 'bold 17px "Barlow Condensed", Arial'
          ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
          ctx.fillText(String(Math.round(max * t / step) * step), Math.cos(a) * r * 0.66, Math.sin(a) * r * 0.66)
        }
      }
      const a = a0 + (a1 - a0) * clamp(value / max, 0, 1)
      ctx.strokeStyle = '#ff6a1a'; ctx.lineWidth = 4
      ctx.beginPath(); ctx.moveTo(Math.cos(a) * r * 0.18, Math.sin(a) * r * 0.18); ctx.lineTo(Math.cos(a) * r * 0.78, Math.sin(a) * r * 0.78); ctx.stroke()
      ctx.fillStyle = '#ff6a1a'; ctx.beginPath(); ctx.arc(0, 0, 6, 0, TAU); ctx.fill()
      ctx.fillStyle = '#98a3ac'; ctx.font = '600 15px Inter, Arial'; ctx.textAlign = 'center'
      ctx.fillText(label, 0, r * 0.54)
      ctx.restore()
    }
    drawGauge(128, 128, 96, speed, 260, 'km/h')
    drawGauge(384, 128, 96, rpm, 8000, 'rpm', 0.78, 500)
    // central digital
    ctx.fillStyle = 'rgba(15,17,20,0.9)'
    ctx.fillRect(212, 68, 88, 125)
    ctx.strokeStyle = 'rgba(255,120,30,0.5)'; ctx.lineWidth = 2; ctx.strokeRect(212, 68, 88, 125)
    ctx.fillStyle = '#ffb066'; ctx.font = '800 72px "Barlow Condensed", Arial'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
    ctx.fillText(gear, 256, 125)
    ctx.font = '600 14px Inter, Arial'; ctx.fillStyle = '#98a3ac'
    ctx.fillText('MARCHA', 256, 168)
    // fuel / temp
    ctx.fillStyle = '#8a949c'; ctx.font = '600 20px "Barlow Condensed", Arial'; ctx.textAlign = 'left'
    ctx.fillText('B S D', 18, 236)
    const blinkOn = Math.floor(performance.now() / 320) % 2 === 0
    if (state.indicator < 0 && blinkOn) { ctx.fillStyle = '#ffb300'; ctx.fillText('◀', 18, 60) }
    if (state.indicator > 0 && blinkOn) { ctx.fillStyle = '#ffb300'; ctx.textAlign = 'right'; ctx.fillText('▶', 494, 60) }
    if (state.headlights) { ctx.fillStyle = '#6fd3ff'; ctx.textAlign = 'left'; ctx.font = '600 18px Inter'; ctx.fillText('LUCES', 18, 32) }
    cockpit.dashTex.needsUpdate = true
    cockpit.spinGroup.rotation.z = -state.steerAngle * 2.4

    // hide via camera? cluster material unmounted when outside - always rendered, cheap
  }

  const visual = {
    spec, group, bodyGroup, wheels, mats, cockpit, panels: { frontBumperMesh, rearBumperMesh },
    updateLights, updateDashboard,
    headGlows, tailGlows, spotL, spotR,
    steerAngle: 0,
    setSteer(a) { state.steerAngle = a; if (cockpit) cockpit.spinGroup.rotation.z = -a * 2.4; for (const w of wheels) if (w.isFront) w.pivot.rotation.y = a },
    setPaint(color) { bodyMat.color.set(color) },
    setWheelSpin(angle) { for (const w of wheels) w.spin.rotation.x = angle },
    dispose() {
      group.traverse(o => {
        if (o.isMesh) { o.geometry?.dispose?.() }
        if (o.isSprite) { o.material?.map?.dispose?.(); o.material?.dispose?.() }
      })
      for (const m of Object.values(mats)) m.dispose?.()
    }
  }
  group.userData.carVisual = visual
  group.userData.bodyGroup = bodyGroup
  return visual
}

import * as THREE from 'three'
import { clamp, lerp, damp } from '../utils.js'
import { TUNE_ITEMS } from '../data/cars.js'

const G = 9.81

function torqueCurve(rpm, spec) {
  const limit = spec.limit
  const idle = spec.idle
  const p = [
    [idle, 0.42], [limit * 0.22, 0.72], [Math.min(spec.torqueRpm, limit * 0.55), 1.0],
    [limit * 0.78, 0.94], [limit * 0.92, 0.82], [limit, 0.58]
  ]
  if (rpm <= p[0][0]) return p[0][1]
  for (let i = 1; i < p.length; i++) {
    if (rpm <= p[i][0]) {
      const t = (rpm - p[i - 1][0]) / (p[i][0] - p[i - 1][0])
      return lerp(p[i - 1][1], p[i][1], clamp(t, 0, 1))
    }
  }
  return p[p.length - 1][1]
}

export class Vehicle {
  constructor(spec, tuning = {}) {
    this.spec = spec
    this.tuning = tuning
    this.position = new THREE.Vector3()
    this.yaw = 0
    this.u = 0
    this.v = 0
    this.yawRate = 0
    this.steer = 0
    this.steerAngle = 0
    this.rpm = 0
    this.gear = 1
    this.gearbox = 'auto'
    this.engineOn = false
    this.starter = 0
    this.shiftTimer = 0
    this.autoShift = 0
    this.reverseHold = 0
    this.clutch = 1
    this.handbrake = false
    this.throttle = 0
    this.brake = 0
    this.speed = 0
    this.wheelSpin = 0
    this.damage = 0
    this.onRoad = true
    this.surfaceGrip = 1
    this.pitch = 0
    this.roll = 0
    this.bodyY = 0
    this.accelG = 0
    this.latG = 0
    this.lateralSlip = 0
    this.drift = 0
    this.lightsOn = false
    this.indicator = 0
    this.impactFlash = 0
    this.lastImpact = 0
    this.airborne = false
    this.suspension = [0, 0, 0, 0]
    this.wheelGround = [0, 0, 0, 0]
    this.revLimiter = 0
    this.engineHealth = 1
    this.fuel = 1
    this.odo = 0
    this.absActive = false
    this.tcsActive = false
    this.lastCrashSpeed = 0
    this.shiftRequest = 0
    this.engineStall = false
    this.startCooldown = 0
    this.applyTuning(tuning)
  }

  applyTuning(tuning = {}) {
    this.tuning = tuning
    const T = TUNE_ITEMS
    const lv = (k) => clamp(tuning[k] || 0, 0, 3)
    this.powerMul = T.engine.power[lv('engine')] * T.turbo.power[lv('turbo')]
    this.gripMul = T.tires.grip[lv('tires')] * T.susp.grip[lv('susp')]
    this.brakeMul = T.brakes.brake[lv('brakes')]
    this.weightMul = T.weight.weight[lv('weight')]
    this.rideHeight = T.susp.height[lv('susp')]
    this.mass = this.spec.weight * this.weightMul
    this.invMass = 1 / this.mass
    this.L = this.spec.wheelbase
    this.a = this.L * (1 - this.spec.dist)
    this.b = this.L * this.spec.dist
    this.Iz = this.mass * (this.L * this.L) / 12 + this.mass * 0.45
    const topMs = this.spec.topSpeed / 3.6
    this.dragC = (this.spec.power * 735 * 0.85) / (topMs * topMs * topMs) * 0.5
    this.dragC = clamp(this.dragC, 0.25, 0.9)
  }

  get kmh() { return Math.abs(this.u) * 3.6 }
  get gearLabel() {
    if (!this.engineOn) return '—'
    if (this.gear === -1) return 'R'
    if (this.gear === 0) return 'N'
    return String(this.gear)
  }
  get gearRatio() {
    if (this.gear === -1) return this.spec.gears[0] * 0.9
    if (this.gear === 0) return 0
    return this.spec.gears[clamp(this.gear - 1, 0, this.spec.gears.length - 1)]
  }
  get driveSpeed() { return Math.abs(this.u) }

  reset(x, z, yaw, groundY = 0) {
    this.position.set(x, groundY, z)
    this.yaw = yaw
    this.u = 0; this.v = 0; this.yawRate = 0
    this.gear = 1; this.rpm = 0; this.engineOn = false; this.starter = 0
    this.damage = 0; this.shiftTimer = 0; this.wheelSpin = 0
    this.throttle = 0; this.brake = 0; this.steer = 0; this.steerAngle = 0
    this.pitch = 0; this.roll = 0; this.bodyY = 0
    this.drift = 0; this.lateralSlip = 0; this.absActive = false; this.tcsActive = false
    this.airborne = false
    this.engineOn = false
    this.lastCrashSpeed = 0
  }

  startEngine() {
    if (this.engineOn || this.starter > 0) return
    this.starter = 1.15
    this.startCooldown = 1.6
  }
  stopEngine() {
    this.engineOn = false
    this.starter = 0
  }
  toggleEngine() {
    if (this.engineOn) this.stopEngine()
    else this.startEngine()
  }

  shiftUp() {
    if (this.gearbox === 'auto') return
    if (this.shiftTimer > 0) return
    if (this.gear < this.spec.gears.length) { this.gear++; this.shiftTimer = 0.22 }
  }
  shiftDown() {
    if (this.gearbox === 'auto') return
    if (this.shiftTimer > 0) return
    if (this.gear > 0) { this.gear--; this.shiftTimer = 0.18 }
    else if (this.gear === 0 && Math.abs(this.u) < 1.2) { this.gear = -1; this.shiftTimer = 0.2 }
  }

  crash(impactSpeed, nx = 0, nz = 0, severity = 1) {
    if (impactSpeed < 1.2) return 0
    const dam = clamp(impactSpeed * 0.95 * severity, 0, 55)
    this.damage = clamp(this.damage + dam * (1 - this.damage / 145), 0, 100)
    this.lastCrashSpeed = impactSpeed
    this.impactFlash = Math.min(1, impactSpeed / 18)
    // velocity loss and bounce (normal in world xz)
    const fx = Math.sin(this.yaw), fz = Math.cos(this.yaw)
    const rx = Math.cos(this.yaw), rz = -Math.sin(this.yaw)
    let u = this.u, v = this.v
    const vwx = fx * u + rx * v, vwz = fz * u + rz * v
    const dot = vwx * nx + vwz * nz
    const bounce = clamp(impactSpeed * 0.22, 0, 3)
    const nvwx = vwx - (1.2) * dot * nx - bounce * nx
    const nvwz = vwz - (1.2) * dot * nz - bounce * nz
    this.u = nvwx * fx + nvwz * fz
    this.v = nvwx * rx + nvwz * rz
    this.yawRate *= 0.7
    if (this.damage > 82) this.engineOn = false
    if (this.damage > 45) this.engineHealth = 1 - (this.damage - 45) * 0.006
    return dam
  }

  repair() {
    this.damage = 0
    this.engineHealth = 1
    this.impactFlash = 0
  }

  step(dt, input, ground) {
    dt = Math.min(dt, 1 / 40)
    const spec = this.spec
    // ---------- inputs ----------
    const targetThrottle = clamp(input.throttle || 0, 0, 1)
    const targetBrake = clamp(input.brake || 0, 0, 1)
    this.throttle = damp(this.throttle, targetThrottle, 10, dt)
    this.brake = damp(this.brake, targetBrake, 14, dt)
    this.handbrake = !!input.handbrake
    const steerTarget = clamp(input.steer || 0, -1, 1)
    this.steer = damp(this.steer, steerTarget, 9, dt)
    const speed = Math.abs(this.u)
    const maxSteer = 0.58 * (1 - 0.55 * clamp(speed / 55, 0, 1))
    const steerRate = 3.2 + 6 * clamp(1 - speed / 25, 0, 1)
    this.steerAngle = damp(this.steerAngle, this.steer * maxSteer, steerRate, dt)

    // engine start
    if (this.starter > 0) {
      this.starter -= dt
      this.rpm = damp(this.rpm, 260 + Math.random() * 120, 10, dt)
      if (this.starter <= 0) {
        this.engineOn = true
        this.startCooldown = 0.6
        this.rpm = spec.idle + 320
      }
    }
    if (this.startCooldown > 0) this.startCooldown -= dt
    // convenience: throttle while stationary turns the key
    if (!this.engineOn && this.starter <= 0 && this.throttle > 0.35 && speed < 0.5 && this.startCooldown <= 0 && this.damage < 92) {
      this.startEngine()
    }

    // gearbox mode
    if (input.gearbox) this.gearbox = input.gearbox
    const clutchInput = input.clutch != null ? clamp(input.clutch, 0, 1) : 0
    this.manualClutch = input.manualClutch && clutchInput > 0.45
    this.clutch = damp(this.clutch, this.manualClutch ? 0 : 1, 8, dt)

    if (this.shiftTimer > 0) this.shiftTimer -= dt
    if (this.gearbox === 'auto' && this.engineOn) this.autoGear(dt, speed)
    if (input.shiftUp) this.shiftUp()
    if (input.shiftDown) this.shiftDown()

    // auto reverse handling
    if (this.gear > 0 && this.brake > 0.5 && speed < 0.45 && this.throttle < 0.1 && this.engineOn) {
      this.reverseHold += dt
      if (this.reverseHold > 0.55) { this.gear = -1; this.reverseHold = 0 }
    } else if (this.gear === -1 && (this.throttle > 0.2 || speed > 1.5)) {
      this.reverseHold += dt
      if (this.reverseHold > 0.3) { this.gear = 1; this.reverseHold = 0 }
    } else {
      this.reverseHold = Math.max(0, this.reverseHold - dt * 2)
    }

    // ---------- engine / rpm ----------
    const ratio = this.gearRatio
    let wheelRpm = 0
    if (this.gear !== 0) wheelRpm = speed / spec.wheelR * ratio * spec.final * 60 / (2 * Math.PI)
    let targetRpm
    if (!this.engineOn) targetRpm = 0
    else if (this.manualClutch || this.gear === 0 || Math.abs(this.u) < 0.7) {
      targetRpm = spec.idle + (spec.limit - spec.idle) * this.throttle * 0.55
    } else {
      targetRpm = wheelRpm + this.throttle * 220
      if (this.shiftTimer > 0) targetRpm -= 400
    }
    if (this.engineOn && input.rev && speed < 2) targetRpm = spec.limit * 0.65
    targetRpm = clamp(targetRpm, this.engineOn ? spec.idle : 0, spec.limit)
    this.rpm = damp(this.rpm, targetRpm, this.manualClutch ? 7 : 14, dt)
    this.revLimiter = targetRpm >= spec.limit - 40 ? 1 : 0
    if (this.rpm > spec.limit - 50) this.rpm = spec.limit - 50

    // damage & health
    this.engineHealth = clamp(1 - Math.max(0, this.damage - 30) * 0.006, 0.55, 1)
    const health = this.engineHealth
    const tc = torqueCurve(this.rpm, spec) * spec.torque * this.powerMul * health
    const gearEff = this.gear === -1 ? -1 : 1
    let drive = this.engineOn ? this.throttle * tc * ratio * spec.final * 0.9 / spec.wheelR * gearEff * this.clutch : 0
    if (this.revLimiter) drive *= 0.15
    if (this.shiftTimer > 0) drive *= 0.15
    // TCS
    this.tcsActive = false
    if (input.tcs !== false && this.engineOn && Math.abs(drive) > 2000) {
      const driveWheelsShare = spec.drivetrain === 'AWD' ? 1 : (spec.drivetrain === 'RWD' ? (1 - spec.dist) : spec.dist)
      const maxTraction = 1.05 * this.mass * G * driveWheelsShare * this.surfaceGrip * this.gripMul
      if (Math.abs(drive) > maxTraction * 1.15) {
        drive = Math.sign(drive) * maxTraction * 1.15
        this.tcsActive = true
      }
    }

    // surface
    const surf = ground ? ground.surfaceAt(this.position.x, this.position.z) : { grip: 1, drag: 0, onRoad: true }
    this.onRoad = surf.onRoad
    this.surfaceGrip = surf.grip
    const mu = (surf.onRoad ? 1.0 : 0.72) * this.gripMul * (surf.wet ? 0.82 : 1) * (1 - this.damage * 0.0015)

    // ---------- longitudinal ----------
    const signU = Math.sign(this.u)
    let Fx = drive
    if (!this.engineOn) Fx = 0
    // engine braking
    if (this.engineOn && this.throttle < 0.08 && this.clutch > 0.5 && speed > 1) {
      Fx -= signU * torqueCurve(this.rpm, spec) * spec.torque * 0.16 * ratio * spec.final * 0.7 / spec.wheelR
    }
    // rolling resistance
    const rollRes = (surf.onRoad ? 0.014 : 0.045) * this.mass * G * Math.sign(this.u)
    Fx -= rollRes
    // aerodynamic drag
    const air = 0.5 * 1.225 * this.dragC * this.u * Math.abs(this.u)
    Fx -= air
    // maximum brake
    const brakeMax = this.mass * G * mu * this.brakeMul
    this.absActive = false
    let brakeForce = 0
    if (this.brake > 0.01) {
      let bf = this.brake * brakeMax * 0.92
      if (input.abs !== false && speed > 2.5 && this.brake > 0.8) {
        // rough ABS modulation when we ask for more than the tyres can take
        const cap = this.mass * G * mu * 0.96
        if (bf > cap) { bf = cap * (0.72 + 0.28 * Math.abs(Math.sin(performance.now() * 0.035))); this.absActive = true }
      }
      brakeForce = Math.min(bf, Math.abs(this.u) * this.mass / Math.max(dt, 0.001))
      Fx -= signU * brakeForce * 0.9
    }
    if (this.handbrake) {
      Fx -= signU * Math.min(this.mass * G * 0.55, Math.abs(this.u) * this.mass / Math.max(dt, 0.001)) * 0.9
    }
    // grade resistance
    if (ground) {
      const slope = ground.slopeAt ? ground.slopeAt(this.position.x, this.position.z, this.yaw) : 0
      Fx -= this.mass * G * Math.sin(slope) * 0.85
    }

    // ---------- lateral / yaw ----------
    const speedSafe = Math.max(Math.abs(this.u), 0.9)
    const alphaF = Math.atan2(this.v + this.yawRate * this.a, speedSafe) - this.steerAngle * Math.sign(this.u || 1)
    const alphaR = Math.atan2(this.v - this.yawRate * this.b, speedSafe)
    // load transfer (approx)
    const axPrev = this.accelG * G
    const h = 0.46
    const Nf = Math.max(120, this.mass * G * (1 - spec.dist) - this.mass * axPrev * h / this.L)
    const Nr = Math.max(120, this.mass * G * spec.dist + this.mass * axPrev * h / this.L)
    const Cf = 62000 * this.gripMul * (surf.onRoad ? 1 : 0.8)
    const Cr = 68000 * this.gripMul * (surf.onRoad ? 1 : 0.75) * (this.handbrake ? 0.42 : 1)
    const gripF = Nf * mu
    const gripR = Nr * mu * (this.handbrake ? 0.48 : 1)
    let Fyf = clamp(-Cf * alphaF, -gripF, gripF)
    let Fyr = clamp(-Cr * alphaR, -gripR, gripR)
    // friction circle: longitudinal use steals lateral capacity
    const rearLongUse = spec.drivetrain === 'RWD' ? Math.abs(drive) * 0.55 : 0
    if (rearLongUse > 0) Fyr *= clamp(1 - rearLongUse / (gripR * 1.3), 0.45, 1)
    if (this.brake > 0.6) { Fyf *= 0.9; Fyr *= 0.86 }
    // low speed blending to a stable kinematic model
    const blend = clamp(Math.abs(this.u) / 4.5, 0, 1)
    const yawKin = (this.u / this.L) * Math.tan(this.steerAngle)
    const yawDyn = (Fyf * Math.cos(this.steerAngle) * this.a - Fyr * this.b) / this.Iz
    let yawAcc = lerp(yawKin * 1.7, yawDyn, blend)
    const latAcc = (Fyf * Math.cos(this.steerAngle) + Fyr) * this.invMass - this.yawRate * this.u
    this.yawRate += yawAcc * dt
    this.yawRate = clamp(this.yawRate, -2.4, 2.4)
    this.yaw += this.yawRate * dt
    this.u += (Fx * this.invMass + this.yawRate * this.v) * dt
    this.v += (latAcc - this.yawRate * this.u) * dt
    // scrub drag from sliding sideways
    const scrub = Math.abs(this.v) * 0.22
    this.u -= Math.sign(this.u) * scrub * dt
    this.v *= Math.exp(-1.1 * dt)
    if (Math.abs(this.u) < 0.06 && this.throttle < 0.05) { this.u *= 0.9; this.v *= 0.9 }
    this.speed = Math.hypot(this.u, this.v)
    this.lateralSlip = Math.abs(this.v)
    this.drift = clamp(Math.abs(this.v) / 9 + Math.abs(this.yawRate) * 0.2, 0, 1)
    this.accelG = damp(this.accelG, (Fx * this.invMass) / G, 4, dt)
    this.latG = damp(this.latG, latAcc / G, 5, dt)
    this.odo += Math.abs(this.u) * dt

    // position
    const fx = Math.sin(this.yaw), fz = Math.cos(this.yaw)
    const rx = Math.cos(this.yaw), rz = -Math.sin(this.yaw)
    this.position.x += (fx * this.u + rx * this.v) * dt
    this.position.z += (fz * this.u + rz * this.v) * dt

    // ground / suspension
    let gy = 0
    if (ground) {
      const halfTrack = spec.track * 0.5
      const halfBase = this.L * 0.5
      const pts = [
        [this.position.x + fx * halfBase - rx * halfTrack, this.position.z + fz * halfBase - rz * halfTrack],
        [this.position.x + fx * halfBase + rx * halfTrack, this.position.z + fz * halfBase + rz * halfTrack],
        [this.position.x - fx * halfBase - rx * halfTrack, this.position.z - fz * halfBase - rz * halfTrack],
        [this.position.x - fx * halfBase + rx * halfTrack, this.position.z - fz * halfBase + rz * halfTrack]
      ]
      let minY = Infinity, maxY = -Infinity, sum = 0
      pts.forEach(([x, z], i) => {
        const y = ground.heightAt(x, z)
        this.wheelGround[i] = y
        minY = Math.min(minY, y); maxY = Math.max(maxY, y); sum += y
      })
      gy = sum / 4
      const pitchGround = Math.atan2((this.wheelGround[0] + this.wheelGround[1]) / 2 - (this.wheelGround[2] + this.wheelGround[3]) / 2, this.L)
      const rollGround = Math.atan2((this.wheelGround[1] + this.wheelGround[3]) / 2 - (this.wheelGround[0] + this.wheelGround[2]) / 2, spec.track)
      const pitchDyn = clamp(-this.accelG * 0.055, -0.055, 0.055)
      const rollDyn = clamp(this.latG * 0.045, -0.055, 0.055)
      this.pitch = damp(this.pitch, pitchGround + pitchDyn, 7, dt)
      this.roll = damp(this.roll, rollGround + rollDyn, 7, dt)
      const bump = surf.onRoad ? 0 : Math.sin(this.odo * 1.7) * 0.012 * clamp(speed / 10, 0, 1)
      this.bodyY = damp(this.bodyY, gy + this.rideHeight + bump, 14, dt)
      const grounded = Math.abs(gy - this.position.y) < 0.6
      this.airborne = !grounded
    }
    this.position.y = damp(this.position.y, gy, 12, dt)
    if (this.position.y < -8) { this.position.y = 0.5 }

    // wheels
    this.wheelSpin += (this.u / spec.wheelR) * dt
    if (this.impactFlash > 0) this.impactFlash = Math.max(0, this.impactFlash - dt * 1.2)
    this.fuel = Math.max(0, this.fuel - dt * Math.abs(this.u) * 0.00012)
    if (this.fuel <= 0) this.engineOn = false
  }

  autoGear(dt, speed) {
    if (this.shiftTimer > 0) return
    this.autoShift += dt
    const upAt = this.spec.dieselLike ? 0.82 : 0.9
    const downAt = 0.36
    if (this.rpm > this.spec.limit * upAt && this.gear < this.spec.gears.length && this.gear > 0) {
      this.gear++; this.shiftTimer = 0.28; this.autoShift = 0
    } else if (this.rpm < this.spec.limit * downAt && this.gear > 1 && this.autoShift > 0.5) {
      this.gear--; this.shiftTimer = 0.2; this.autoShift = 0
    }
  }
}

import * as THREE from 'three'
import { RIVER, WORLD_SIZE } from '../data/mapData.js'
import { clamp, lerp, smoothstep } from '../utils.js'

export const SEA_LEVEL = -2.4

function hash2(x, z) {
  const n = Math.sin(x * 127.1 + z * 311.7 + 13.7) * 43758.5453123
  return n - Math.floor(n)
}
function noise2(x, z) {
  const xi = Math.floor(x), zi = Math.floor(z)
  const xf = x - xi, zf = z - zi
  const u = xf * xf * (3 - 2 * xf)
  const v = zf * zf * (3 - 2 * zf)
  const a = hash2(xi, zi), b = hash2(xi + 1, zi), c = hash2(xi, zi + 1), d = hash2(xi + 1, zi + 1)
  return lerp(lerp(a, b, u), lerp(c, d, u), v)
}
function fbm(x, z) {
  return noise2(x, z) * 0.58 + noise2(x * 2.13 + 5, z * 2.13 + 7) * 0.28 + noise2(x * 4.7, z * 4.7) * 0.14
}
function gauss(x, z, cx, cz, s) {
  const dx = x - cx, dz = z - cz
  return Math.exp(-(dx * dx + dz * dz) / (2 * s * s))
}

// Polyline of the Nervión / estuary; used for carving and water scenery.
const RIVER_LINE = RIVER.map(([x, z]) => new THREE.Vector2(x, z))
export function distToRiver(x, z) {
  const p = new THREE.Vector2(x, z)
  let best = 1e9
  for (let i = 0; i < RIVER_LINE.length - 1; i++) {
    const a = RIVER_LINE[i], b = RIVER_LINE[i + 1]
    const ab = b.clone().sub(a)
    const t = clamp(p.clone().sub(a).dot(ab) / ab.lengthSq(), 0, 1)
    const d = p.distanceTo(a.clone().addScaledVector(ab, t))
    if (d < best) best = d
  }
  return best
}

const COAST = [
  [-1750, -1750], [-1750, -330], [-1450, -500], [-1240, -870], [-1050, -1130],
  [-800, -1330], [-400, -1450], [0, -1560], [420, -1700], [900, -1750]
]
function pointInPoly(x, z, poly) {
  let inside = false
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, zi] = poly[i], [xj, zj] = poly[j]
    if ((zi > z) !== (zj > z) && x < (xj - xi) * (z - zi) / (zj - zi) + xi) inside = !inside
  }
  return inside
}

export class HeightField {
  constructor() {
    this.size = WORLD_SIZE
    this.half = WORLD_SIZE / 2
    this.N = 400
    this.cell = WORLD_SIZE / this.N
    this.base = new Float32Array((this.N + 1) * (this.N + 1))
    this.RN = 760
    this.rcell = WORLD_SIZE / this.RN
    this.roadDist = new Float32Array((this.RN + 1) * (this.RN + 1)).fill(999)
    this.roadY = new Float32Array((this.RN + 1) * (this.RN + 1))
    this.roadHalf = new Float32Array((this.RN + 1) * (this.RN + 1)).fill(6)
    this.roadBridge = new Uint8Array((this.RN + 1) * (this.RN + 1))
    this.buildBase()
  }

  riverDist(x, z) { return distToRiver(x, z) }

  baseHeight(x, z) {
    let h = 1.2
    h += 128 * gauss(x, z, 960, 1120, 470)
    h += 74 * gauss(x, z, 300, 1330, 520)
    h += 92 * gauss(x, z, -950, 760, 470)
    h += 58 * gauss(x, z, -1330, 220, 340)
    h += 42 * gauss(x, z, -600, -980, 330)
    h += 52 * gauss(x, z, 830, 560, 390)
    h += 60 * gauss(x, z, 440, -240, 240)
    h -= 12 * gauss(x, z, 200, 120, 900)
    const urban = gauss(x, z, 260, 170, 760) * 0.92 + gauss(x, z, -520, -220, 520) * 0.6 + gauss(x, z, -1050, -620, 400) * 0.55
    h *= (1 - clamp(urban, 0, 0.9))
    // river valley
    const rd = distToRiver(x, z)
    h -= 26 * smoothstep(170, 15, rd)
    // gentle coastal slope
    if (pointInPoly(x, z, COAST)) h -= 15
    // small scale relief
    h += (fbm(x * 0.012, z * 0.012) - 0.5) * 9 + (fbm(x * 0.05 + 11, z * 0.05 + 3) - 0.5) * 1.6
    // flatten the city plain
    h = lerp(h, 1.8 + (fbm(x * 0.02, z * 0.02) - 0.5) * 0.6, clamp(urban, 0, 0.9))
    h = Math.max(h, SEA_LEVEL - 6)
    return h
  }

  buildBase() {
    const N = this.N
    for (let iz = 0; iz <= N; iz++) {
      for (let ix = 0; ix <= N; ix++) {
        const x = -this.half + ix * this.cell
        const z = -this.half + iz * this.cell
        this.base[iz * (N + 1) + ix] = this.baseHeight(x, z)
      }
    }
  }

  baseAt(x, z) {
    const fx = clamp((x + this.half) / this.cell, 0, this.N - 0.001)
    const fz = clamp((z + this.half) / this.cell, 0, this.N - 0.001)
    const ix = Math.floor(fx), iz = Math.floor(fz)
    const tx = fx - ix, tz = fz - iz
    const i0 = iz * (this.N + 1) + ix
    const a = this.base[i0], b = this.base[i0 + 1]
    const c = this.base[i0 + this.N + 1], d = this.base[i0 + this.N + 2]
    return lerp(lerp(a, b, tx), lerp(c, d, tx), tz)
  }

  stampRoad(x, z, y, halfWidth, bridge = false) {
    const pad = halfWidth + 9
    const i0 = clamp(Math.floor((x - pad + this.half) / this.rcell), 0, this.RN)
    const i1 = clamp(Math.ceil((x + pad + this.half) / this.rcell), 0, this.RN)
    const j0 = clamp(Math.floor((z - pad + this.half) / this.rcell), 0, this.RN)
    const j1 = clamp(Math.ceil((z + pad + this.half) / this.rcell), 0, this.RN)
    for (let j = j0; j <= j1; j++) {
      for (let i = i0; i <= i1; i++) {
        const px = -this.half + i * this.rcell
        const pz = -this.half + j * this.rcell
        const d = Math.hypot(px - x, pz - z)
        const idx = j * (this.RN + 1) + i
        if (d < this.roadDist[idx]) {
          this.roadDist[idx] = d
          this.roadY[idx] = y
          this.roadHalf[idx] = halfWidth
          this.roadBridge[idx] = bridge ? 1 : 0
        }
      }
    }
  }

  roadInfoAt(x, z) {
    const ix = clamp(Math.round((x + this.half) / this.rcell), 0, this.RN)
    const iz = clamp(Math.round((z + this.half) / this.rcell), 0, this.RN)
    const idx = iz * (this.RN + 1) + ix
    return { dist: this.roadDist[idx], y: this.roadY[idx], half: this.roadHalf[idx], bridge: this.roadBridge[idx] === 1 }
  }

  heightAt(x, z) {
    const base = this.baseAt(x, z)
    const info = this.roadInfoAt(x, z)
    if (info.dist < info.half + 0.4) {
      if (info.bridge) return info.dist < info.half ? info.y : base
      return info.y
    }
    if (info.dist < info.half + 8) {
      const w = 1 - smoothstep(info.half, info.half + 8, info.dist)
      if (info.bridge) return base
      return lerp(base, info.y, w)
    }
    return base
  }

  surfaceAt(x, z) {
    const info = this.roadInfoAt(x, z)
    const onRoad = info.dist < info.half + 0.35
    return { onRoad, road: onRoad, roadType: onRoad ? 1 : 0, grip: onRoad ? 1 : 0.72 }
  }

  slopeAt(x, z, yaw) {
    const fx = Math.sin(yaw), fz = Math.cos(yaw)
    const d = 1.6
    const hf = this.heightAt(x + fx * d, z + fz * d)
    const hb = this.heightAt(x - fx * d, z - fz * d)
    return Math.atan2(hf - hb, d * 2)
  }

  isInSea(x, z) {
    return pointInPoly(x, z, COAST)
  }

  // grid of colors sampled for the terrain mesh
  terrainColor(x, z, h, slope, urban) {
    const c = new THREE.Color()
    const rd = distToRiver(x, z)
    if (h < SEA_LEVEL + 0.8) {
      c.set('#6c6652')
    } else if (rd < 55) {
      c.set('#6f6a54')
    } else if (h > 82) {
      c.set('#6e6c66').lerp(new THREE.Color('#4e5a44'), clamp(1 - (h - 82) / 60, 0, 1))
    } else {
      const green = new THREE.Color('#547a3c').lerp(new THREE.Color('#6f8f4a'), fbm(x * 0.03, z * 0.03))
      const dry = new THREE.Color('#87804f')
      c.copy(green).lerp(dry, clamp((fbm(x * 0.008 + 4, z * 0.008) - 0.42) * 1.4, 0, 0.5))
      if (urban > 0.3) c.lerp(new THREE.Color('#7e7b72'), clamp(urban * 0.78, 0, 0.72))
      if (slope > 0.5) c.lerp(new THREE.Color('#77736b'), clamp((slope - 0.5) * 0.8, 0, 0.5))
    }
    return c
  }
}

import * as THREE from 'three'
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js'
import { clamp, lerp, TAU, asphaltTexture, concreteTexture } from '../utils.js'
import { ROADS, WORLD_SIZE } from '../data/mapData.js'

const paintMat = new THREE.MeshStandardMaterial({ color: 0xf0efe6, roughness: 0.55, metalness: 0.02, emissive: 0xffffff, emissiveIntensity: 0.04 })
const guardMat = new THREE.MeshStandardMaterial({ color: 0xb8bdc1, roughness: 0.42, metalness: 0.82 })
const poleMat = new THREE.MeshStandardMaterial({ color: 0x5d6165, roughness: 0.55, metalness: 0.55 })
const lampMat = new THREE.MeshStandardMaterial({ color: 0xd9dde0, emissive: 0xffd9a0, emissiveIntensity: 0.0, roughness: 0.3 })
const tunnelMat = new THREE.MeshStandardMaterial({ color: 0x605e59, roughness: 0.94, metalness: 0.02, side: THREE.DoubleSide })
const tunnelLightMat = new THREE.MeshBasicMaterial({ color: 0xffd9a0 })
const sidewalkMat = new THREE.MeshStandardMaterial({ map: concreteTexture('#918e86'), color: 0xbfbcb3, roughness: 0.92, metalness: 0.02 })
const curbMat = new THREE.MeshStandardMaterial({ color: 0xaaa79e, roughness: 0.9 })

function ribbon(samples, fromOff, toOff, yOff = 0, closed = false, n = null) {
  const pts = []
  const uvs = []
  const idx = []
  const src = n ? n : samples.length
  let acc = 0
  for (let i = 0; i < src; i++) {
    const s = samples[i]
    if (i > 0) acc += Math.hypot(s.x - samples[i - 1].x, s.z - samples[i - 1].z)
    const rx = s.tz, rz = -s.tx
    pts.push(s.x + rx * fromOff, s.y + yOff, s.z + rz * fromOff)
    pts.push(s.x + rx * toOff, s.y + yOff, s.z + rz * toOff)
    uvs.push(0, acc / 6, 1, acc / 6)
    if (i > 0) {
      const b = (i - 1) * 2
      idx.push(b, b + 1, b + 2, b + 1, b + 3, b + 2)
    }
  }
  if (closed && src > 2) {
    const b = (src - 1) * 2
    idx.push(b, b + 1, 0, b + 1, 1, 0)
  }
  const g = new THREE.BufferGeometry()
  g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3))
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2))
  g.setIndex(idx)
  g.computeVertexNormals()
  return g
}

function markings(samples, offset, width, dash = 0, gap = 0, closed = true) {
  const geo = []
  const total = samples[samples.length - 1].d
  if (dash > 0) {
    for (let d = 0; d < total; d += dash + gap) {
      const a = sampleAt(samples, d, closed)
      const b = sampleAt(samples, Math.min(total - 0.02, d + dash), closed)
      if (!a || !b) continue
      const aw = width / 2
      const vertices = [
        [a.x + a.tz * (offset - aw), a.y + 0.075, a.z - a.tx * (offset - aw)],
        [a.x + a.tz * (offset + aw), a.y + 0.075, a.z - a.tx * (offset + aw)],
        [b.x + b.tz * (offset - aw), b.y + 0.075, b.z - b.tx * (offset - aw)],
        [b.x + b.tz * (offset + aw), b.y + 0.075, b.z - b.tx * (offset + aw)]
      ]
      geo.push(vertices)
    }
  } else {
    const g = ribbon(samples, offset - width / 2, offset + width / 2, 0.075, closed)
    return g
  }
  const positions = []
  for (const q of geo) positions.push(...q[0], ...q[1], ...q[2], ...q[1], ...q[3], ...q[2])
  const g = new THREE.BufferGeometry()
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  g.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array((positions.length / 3) * 2), 2))
  g.computeVertexNormals()
  return g
}

export function sampleAt(samples, d, closed) {
  const n = samples.length
  if (!n) return null
  const total = samples[n - 1].d
  if (closed) d = ((d % total) + total) % total
  else d = clamp(d, 0, total - 0.001)
  let lo = 0, hi = n - 1
  while (lo < hi - 1) {
    const mid = (lo + hi) >> 1
    if (samples[mid].d <= d) lo = mid; else hi = mid
  }
  const a = samples[lo], b = samples[Math.min(n - 1, lo + 1)]
  const t = (d - a.d) / Math.max(0.0001, b.d - a.d)
  return {
    x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t), z: lerp(a.z, b.z, t),
    tx: lerp(a.tx, b.tx, t), tz: lerp(a.tz, b.tz, t),
    d
  }
}

export class Road {
  constructor(data, heightField) {
    this.data = data
    this.hf = heightField
    this.id = data.id
    this.name = data.name
    this.kind = data.kind
    this.width = data.width
    this.half = data.width / 2
    this.closed = !!data.closed
    this.lanes = data.lanes || 2
    const pts = data.points.map(([x, z]) => new THREE.Vector3(x, 0, z))
    this.curve = new THREE.CatmullRomCurve3(pts, this.closed, 'centripetal', 0.4)
    this.curveLength = this.curve.getLength()
    const n = Math.max(24, Math.ceil(this.curveLength / 3))
    const raw = this.curve.getSpacedPoints(n)
    if (this.closed) raw.pop()
    const count = raw.length
    const ys = new Float32Array(count)
    for (let i = 0; i < count; i++) {
      const p = raw[i]
      let y = heightField.baseHeight(p.x, p.z)
      y = Math.max(y, 1.9)
      if (data.bridge) y = Math.max(y, 6.3)
      ys[i] = y
    }
    // smooth longitudinal profile
    for (let pass = 0; pass < (data.bridge ? 2 : 5); pass++) {
      const copy = ys.slice()
      for (let i = 0; i < count; i++) {
        const prev = this.closed ? (i - 1 + count) % count : Math.max(0, i - 1)
        const next = this.closed ? (i + 1) % count : Math.min(count - 1, i + 1)
        ys[i] = (copy[prev] + copy[i] * 2 + copy[next]) / 4
      }
    }
    // max grade limiting
    const step = this.curveLength / count
    for (let pass = 0; pass < 3; pass++) {
      for (let i = 1; i < count; i++) {
        const maxD = 0.145 * step
        if (ys[i] > ys[i - 1] + maxD) ys[i] = ys[i - 1] + maxD
        if (ys[i] < ys[i - 1] - maxD) ys[i] = ys[i - 1] - maxD
      }
    }
    if (data.bridge) {
      for (let i = 0; i < count; i++) ys[i] = Math.max(ys[i], 4.6)
    }
    const samples = []
    let acc = 0
    for (let i = 0; i < count; i++) {
      const p = raw[i]
      const prev = raw[this.closed ? (i - 1 + count) % count : Math.max(0, i - 1)]
      const next = raw[this.closed ? (i + 1) % count : Math.min(count - 1, i + 1)]
      let tx = next.x - prev.x, tz = next.z - prev.z
      const len = Math.hypot(tx, tz) || 1
      tx /= len; tz /= len
      if (i > 0) acc += Math.hypot(p.x - samples[i - 1].x, p.z - samples[i - 1].z)
      samples.push({ x: p.x, y: ys[i], z: p.z, tx, tz, d: acc, half: this.half })
    }
    this.samples = samples
    this.total = acc
    this.step = step
    const lw = this.width / this.lanes
    this.laneCenters = []
    for (let i = 0; i < this.lanes / 2; i++) this.laneCenters.push(this.half - lw * (i + 0.5))
    this.colliders = []
    this.lampPositions = []
    this.trafficLights = []
  }

  at(d) { return sampleAt(this.samples, d, this.closed) }
  atT(t) { return this.at(t * this.total) }
  nearestPoint(x, z) {
    let best = null, bd = 1e9
    for (let i = 0; i < this.samples.length; i += 2) {
      const s = this.samples[i]
      const d = (s.x - x) ** 2 + (s.z - z) ** 2
      if (d < bd) { bd = d; best = s }
    }
    return best
  }
}

export class RoadNetwork {
  constructor(scene, heightField) {
    this.scene = scene
    this.hf = heightField
    this.roads = []
    this.byId = {}
    this.paintGeos = []
    this.lampPositions = []
    this.guardGeos = []
    this.poleGeos = []
    this.speedSigns = []
    this.asphalt = asphaltTexture()
    this.asphalt.wrapS = this.asphalt.wrapT = THREE.RepeatWrapping
    this.asphaltMat = new THREE.MeshStandardMaterial({
      map: this.asphalt, color: 0x9a9a9a, roughness: 0.86, metalness: 0.06
    })
    this.build()
  }

  build() {
    for (const data of ROADS) {
      const road = new Road(data, this.hf)
      this.roads.push(road)
      this.byId[road.id] = road
      for (const s of road.samples) {
        this.hf.stampRoad(s.x, s.z, s.y, road.half, !!data.bridge)
      }
    }
    for (const road of this.roads) this.buildMeshes(road)
    this.flushMerged()
  }

  flushMerged() {
    if (this.paintGeos.length) {
      const merged = mergeGeometries(this.paintGeos, false)
      if (merged) {
        const m = new THREE.Mesh(merged, paintMat)
        m.receiveShadow = false
        this.scene.add(m)
      }
      this.paintGeos = []
    }
    if (this.guardGeos.length) {
      const merged = mergeGeometries(this.guardGeos, false)
      if (merged) {
        const m = new THREE.Mesh(merged, guardMat)
        m.castShadow = false; m.receiveShadow = false
        this.scene.add(m)
      }
      this.guardGeos = []
    }
    if (this.poleGeos.length) {
      const merged = mergeGeometries(this.poleGeos, false)
      if (merged) {
        const m = new THREE.Mesh(merged, poleMat)
        m.castShadow = false; m.receiveShadow = true
        this.scene.add(m)
      }
      this.poleGeos = []
    }
  }

  buildMeshes(road) {
    const d = road.data
    const closed = road.closed
    // main asphalt
    const asphaltGeo = ribbon(road.samples, -road.half, road.half, 0.045, closed)
    const roadMesh = new THREE.Mesh(asphaltGeo, this.asphaltMat)
    roadMesh.receiveShadow = true
    roadMesh.castShadow = false
    this.scene.add(roadMesh)

    // curbs / sidewalk
    const sw = d.sidewalks || 0
    if (sw > 0.4) {
      for (const side of [-1, 1]) {
        const from = side * (road.half + 0.02)
        const to = side * (road.half + sw)
        const g = ribbon(road.samples, from, to, 0.135, closed)
        const m = new THREE.Mesh(g, sidewalkMat)
        m.receiveShadow = true
        this.scene.add(m)
        const curb = ribbon(road.samples, side * (road.half - 0.01), side * (road.half + 0.16), 0.16, closed)
        const cm = new THREE.Mesh(curb, curbMat)
        cm.receiveShadow = true
        this.scene.add(cm)
      }
    }
    // markings
    if (this.paintGeos.length > 1200) this.flushMerged()
    const edge = road.half - 0.42
    if (d.kind !== 'bridge' || true) {
      this.paintGeos.push(markings(road.samples, -edge, 0.10, 0, 0, closed))
      this.paintGeos.push(markings(road.samples, edge, 0.10, 0, 0, closed))
    }
    if (d.lanes >= 4) {
      this.paintGeos.push(markings(road.samples, 0, 0.10, 0, 0, closed))
      this.paintGeos.push(markings(road.samples, -road.half * 0.5, 0.11, 3.5, 7, closed))
      this.paintGeos.push(markings(road.samples, road.half * 0.5, 0.11, 3.5, 7, closed))
    } else {
      this.paintGeos.push(markings(road.samples, 0, 0.11, 3.5, 7, closed))
    }

    // guardrails
    if (d.guardrail) {
      for (let dist = 0; dist < road.total; dist += 6) {
        for (const side of [-1, 1]) {
          const a = road.at(dist)
          if (!a) continue
          const off = side * (road.half + 0.5)
          const x = a.x + a.tz * off
          const z = a.z - a.tx * off
          const y = a.y
          const post = new THREE.BoxGeometry(0.08, 0.72, 0.08)
          post.translate(x, y + 0.36, z)
          this.guardGeos.push(post)
          if (dist % 12 === 0) {
            const rail = new THREE.BoxGeometry(0.12, 0.3, 6.1)
            const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), Math.atan2(a.tx, a.tz))
            rail.applyQuaternion(q)
            rail.translate(x, y + 0.62, z)
            this.guardGeos.push(rail)
          }
          if (dist % 12 === 0) {
            road.colliders.push({ x, z, hw: 0.22, hd: 3.0, angle: Math.atan2(a.tx, a.tz), h: 0.8 })
          }
        }
      }
    }
    // lamps
    if (d.lamps > 0) {
      const lampStep = d.lamps
      for (let dist = 4; dist < road.total; dist += lampStep) {
        const a = road.at(dist)
        if (!a) continue
        const sides = d.kind === 'highway' ? [1] : [1, -1]
        for (const side of sides) {
          const off = side * (road.half + (sw > 0.4 ? 0.7 : 0.9))
          const bx = a.x + a.tz * off, bz = a.z - a.tx * off
          const baseY = this.hf.heightAt(bx, bz)
          const y = Math.max(a.y, baseY)
          // pole
          const pole = new THREE.CylinderGeometry(0.07, 0.10, 7.2, 6)
          pole.translate(bx, y + 3.6, bz)
          this.poleGeos.push(pole)
          // arm towards road
          const arm = new THREE.BoxGeometry(0.09, 0.09, 2.1)
          const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), Math.atan2(a.tz, -a.tx))
          arm.applyQuaternion(q)
          arm.translate(bx - a.tz * side * 1.0, y + 7.1, bz + a.tx * side * 1.0)
          this.poleGeos.push(arm)
          const hx = bx - a.tz * side * 2.0, hz = bz + a.tx * side * 2.0
          const head = new THREE.BoxGeometry(0.55, 0.14, 0.28)
          head.translate(hx, y + 7.05, hz)
          // merge heads separately because they share a different material
          if (!this.lampGeo) this.lampGeo = []
          this.lampGeo.push(head)
          road.lampPositions.push({ x: hx, y: y + 6.9, z: hz })
          this.lampPositions.push({ x: hx, y: y + 6.9, z: hz })
        }
      }
    }
    // tunnel geometry
    if (d.tunnels) {
      for (const [t0, t1] of d.tunnels) this.buildTunnel(road, t0, t1)
    }
    // bus stop / benches for city
    if (d.kind === 'city' && d.density > 0.8) {
      for (let i = 0; i < 3; i++) {
        const a = road.atT(0.18 + i * 0.27)
        const off = road.half + sw + 0.9
        const bx = a.x + a.tz * off, bz = a.z - a.tx * off
        const y = this.hf.heightAt(bx, bz)
        const mat = new THREE.MeshStandardMaterial({ color: 0x2d343b, roughness: 0.6, metalness: 0.4 })
        const glass = new THREE.MeshStandardMaterial({ color: 0x88a6b5, roughness: 0.2, metalness: 0.5, transparent: true, opacity: 0.5 })
        const shelter = new THREE.Group()
        const roof = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.12, 1.2), mat)
        roof.position.set(bx, y + 2.5, bz)
        const back = new THREE.Mesh(new THREE.BoxGeometry(3.2, 2.1, 0.08), glass)
        back.position.set(bx, y + 1.35, bz + 0.55)
        const bench = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.1, 0.4), new THREE.MeshStandardMaterial({ color: 0x7a6a52, roughness: 0.7 }))
        bench.position.set(bx, y + 0.5, bz)
        shelter.add(roof, back, bench)
        shelter.rotation.y = Math.atan2(a.tx, a.tz)
        this.scene.add(shelter)
      }
    }
    // road-specific scenery props handled by world
  }

  buildTunnel(road, t0, t1) {
    const d0 = t0 * road.total, d1 = t1 * road.total
    const positions = []
    const indices = []
    const lightGeo = []
    const steps = Math.max(8, Math.ceil((d1 - d0) / 5))
    const ringPts = 9
    for (let i = 0; i <= steps; i++) {
      const d = lerp(d0, d1, i / steps)
      const a = road.at(d)
      const rx = a.tz, rz = -a.tx
      for (let j = 0; j <= ringPts; j++) {
        const ang = Math.PI * (j / ringPts)
        const w = road.half + 1.8
        const x = a.x + rx * Math.cos(Math.PI - ang) * w
        const z = a.z + rz * Math.cos(Math.PI - ang) * w
        const y = a.y + Math.sin(ang) * (road.half + 2.5)
        positions.push(x, y, z)
      }
      if (i > 0) {
        const b = (i - 1) * (ringPts + 1)
        const c = i * (ringPts + 1)
        for (let j = 0; j < ringPts; j++) {
          indices.push(b + j, b + j + 1, c + j, b + j + 1, c + j + 1, c + j)
        }
      }
      if (i % 2 === 0) {
        const lx = a.x + a.tz * 0.0, lz = a.z - a.tx * 0.0
        lightGeo.push(lx, a.y + road.half + 1.0, lz)
      }
    }
    const g = new THREE.BufferGeometry()
    g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
    g.setIndex(indices)
    g.computeVertexNormals()
    const mesh = new THREE.Mesh(g, tunnelMat)
    mesh.receiveShadow = true
    this.scene.add(mesh)
    // interior light bars
    const barGeo = []
    for (const [x, y, z] of []) {}
    // portals
    for (const d of [d0, d1]) {
      const a = road.at(d)
      const portal = new THREE.Mesh(new THREE.BoxGeometry(road.half * 2 + 6, 0.8, 2.2), new THREE.MeshStandardMaterial({ color: 0x77736b, roughness: 0.9 }))
      portal.position.set(a.x, a.y + road.half + 2.9, a.z)
      portal.rotation.y = Math.atan2(a.tx, a.tz)
      this.scene.add(portal)
    }
    // emissive ceiling lights
    const lightsMesh = []
    for (let i = 0; i <= steps; i += 3) {
      const a = road.at(lerp(d0, d1, i / steps))
      const lg = new THREE.BoxGeometry(0.25, 0.08, 1.2)
      lg.translate(a.x, a.y + road.half + 1.7, a.z)
      lightsMesh.push(lg)
    }
    if (lightsMesh.length) {
      const lm = new THREE.Mesh(mergeGeometries(lightsMesh, false), tunnelLightMat)
      this.scene.add(lm)
    }
    // side collisions
    for (let d = d0; d < d1; d += 8) {
      const a = road.at(d)
      for (const side of [-1, 1]) {
        road.colliders.push({
          x: a.x + a.tz * side * (road.half + 1.3), z: a.z - a.tx * side * (road.half + 1.3),
          hw: 0.4, hd: 4.2, angle: Math.atan2(a.tx, a.tz), h: 6
        })
      }
    }
  }

  finalize() {
    this.flushMerged()
    if (this.lampGeo && this.lampGeo.length) {
      const lm = new THREE.Mesh(mergeGeometries(this.lampGeo, false), lampMat)
      this.scene.add(lm)
      this.lampGeo = []
    }
  }

  setWet(wetness) {
    this.asphaltMat.roughness = lerp(0.86, 0.28, wetness)
    this.asphaltMat.metalness = lerp(0.06, 0.5, wetness)
    this.asphaltMat.color.setHex(wetness > 0.4 ? 0x7c7d80 : 0x9a9a9a)
    sidewalkMat.roughness = lerp(0.92, 0.5, wetness)
  }

  findNearestRoad(x, z) {
    let best = null, bd = 1e9
    for (const r of this.roads) {
      const p = r.nearestPoint(x, z)
      if (!p) continue
      const d = Math.hypot(p.x - x, p.z - z)
      if (d < bd) { bd = d; best = r }
    }
    return best
  }

  spawnPoint(roadId, t, lane = 0, dir = 1) {
    const road = this.byId[roadId] || this.roads[0]
    const a = road.atT(t)
    const off = lane * dir
    const x = a.x + a.tz * off, z = a.z - a.tx * off
    const yaw = Math.atan2(dir * a.tx, dir * a.tz)
    return { x, y: road ? this.hf.heightAt(x, z) : 0, z, yaw, road, d: t * road.total }
  }
}

